from dataclasses import dataclass, replace


@dataclass(frozen=True)
class Trade:
    ref: str
    amount: float
    currency: str = 'EUR'

    def converted(self, fx):
        return replace(self, amount=self.amount * fx, currency='USD')

class Portfolio:
    def __init__(self, amounts):
        self.amounts = list(amounts)

    def __len__(self):
        return len(self.amounts)

    def __iter__(self):
        return iter(self.amounts)

    def __contains__(self, x):
        return x in self.amounts

    def __add__(self, other):
        return Portfolio(self.amounts + list(other))

    @property
    def total(self):
        return sum(self.amounts)

def chunks(items, size):
    batch = []
    for item in items:
        batch.append(item)
        if len(batch) == size:
            yield batch
            batch = []
    if batch:
        yield batch

def deep_flatten(x):
    for item in x:
        if isinstance(item, list):
            yield from deep_flatten(item)
        else:
            yield item

def running_total(amounts):
    total = 0
    for a in amounts:
        total += a
        yield total

